<section><div class="page-head"><div><p class="eyebrow">Order workspace</p><h1>Orders</h1><p class="muted"><?= e($orders['total']) ?> order<?= $orders['total']===1?'':'s' ?> for <?= e($store['name']) ?>.</p></div></div>
<form class="order-filters" method="get" action="/merchant/orders"><label class="sr-only" for="order-search">Search orders</label><input id="order-search" name="q" value="<?= e($query) ?>" placeholder="Reference, customer, or phone"><label class="sr-only" for="order-status">Status</label><select id="order-status" name="status"><option value="">All statuses</option><?php foreach($statuses as$item):?><option value="<?= e($item) ?>" <?= $status===$item?'selected':'' ?>><?= e(ucfirst(strtolower($item))) ?></option><?php endforeach ?></select><button class="button secondary" type="submit">Filter</button></form>
<?php if(!$orders['items']):?><div class="panel empty-state"><div class="empty-icon">↗</div><h2><?= $query!==''||$status!==''?'No matching orders':'Your first order will appear here.' ?></h2><p><?= $query!==''||$status!==''?'Try another reference, customer, phone, or status.':'When a customer completes checkout, the saved order will show here before WhatsApp opens.' ?></p><?php if($query!==''||$status!==''):?><a class="button secondary" href="/merchant/orders">Clear filters</a><?php endif ?></div><?php else:?><div class="panel flush table-wrap"><table class="order-table"><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>WhatsApp</th><th>Total</th><th>Placed</th></tr></thead><tbody><?php foreach($orders['items']as$order):?><tr><td><a href="/merchant/orders/<?= e($order['reference']) ?>"><strong><?= e($order['reference']) ?></strong></a></td><td><?= e($order['customer_name']) ?><small><?= e($order['customer_phone']) ?></small></td><td><span class="badge order-<?= e(strtolower($order['status'])) ?>"><?= e(ucfirst(strtolower($order['status']))) ?></span></td><td><?= $order['whatsapp_opened_at']?'Open attempted':'Not opened' ?></td><td><strong><?= e($order['currency_code']) ?> <?= e($order['total']) ?></strong></td><td><?= e(gmdate('M j, Y H:i',strtotime($order['placed_at']))) ?> UTC</td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if($orders['pages']>1):?><nav class="pagination" aria-label="Order pages"><?php $base='/merchant/orders?'.http_build_query(['q'=>$query,'status'=>$status]);if($orders['page']>1):?><a class="button secondary compact" href="<?= e($base.'&page='.($orders['page']-1)) ?>">Previous</a><?php endif ?><span>Page <?= e($orders['page']) ?> of <?= e($orders['pages']) ?></span><?php if($orders['page']<$orders['pages']):?><a class="button secondary compact" href="<?= e($base.'&page='.($orders['page']+1)) ?>">Next</a><?php endif ?></nav><?php endif ?></section>
